package earth.terrarium.pastel.data.lang.guidebook;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class GuidebookIdeas {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("pastel.gui.guidebook.reveal_hint_button.text", "Uncover Insight    ");
		provider.add("pastel.gui.guidebook.reveal_hint_button.tooltip.lacking_resource", "You do not have this in your inventory");
		provider.add("pastel.gui.guidebook.reveal_hint_button.tooltip.pay", "Pay a small fee to reveal an idea");
		
		provider.add("book.pastel.guidebook.idea", "An Idea");
		provider.add("book.pastel.guidebook.ideas.a_gemstone", "About a Gemstone");
		provider.add("book.pastel.guidebook.ideas.a_new_ore", "About a new Ore");
		provider.add("book.pastel.guidebook.ideas.a_new_resource", "About a new Resource");
		provider.add("book.pastel.guidebook.ideas.amethyst.page0.text", "Geodes are usually found deep underground.");
		provider.add("book.pastel.guidebook.ideas.azurite.page0.text", "In some areas just above bedrock I noticed a striking blue aura. I wonder what causes it.");
		provider.add("book.pastel.guidebook.ideas.azurite.page1.text", "These auras, accompanied by soft humming, seem to be caused by giant deposits of rich blue ore! It is buried within rock in rare, but giant clusters.");
		provider.add("book.pastel.guidebook.ideas.citrine.page0.text", "When traveling the world I saw some geodes peek out of the ground close to surface level - most often near shores or ravines.");
		provider.add("book.pastel.guidebook.ideas.clover.page0.text", "I saw some ordinary plants in Plains once! I wasn't too lucky before, but what about now?");
		provider.add("book.pastel.guidebook.ideas.clover.page1.text", "The Clovers I saw growing in small patches in Plains biomes mostly have three leaves, but rarely there is also one with four! Looks like I can even spread them using Bone Meal or the Nature's Staff.");
		provider.add("book.pastel.guidebook.ideas.concise_instructions", "Concise Instructions");
		provider.add("book.pastel.guidebook.ideas.downstone_fragments.page0.text", "The deeper I dug into the underground of Imbrifer, the more often I came across rocks that seemed indestructible. Is that really all there is, or did someone build down there?");
		provider.add("book.pastel.guidebook.ideas.downstone_fragments.page1.text", "Definitely not! Looks like the former inhabitants built giant structures to carve this stone. I am sure they have a bit left over. Something tells me, they won't need it anymore.");
		provider.add("book.pastel.guidebook.ideas.dragonbone.page0.text", "I found the remains of a giant creature.\\\nThese blocks seem to be impossible to mine in the traditional way, since they are protected by a magical aura that quickly reconstructs itself again when trying to mine it.\\\nIs there an unconventional way to break this aura, perhaps using great force?");
		provider.add("book.pastel.guidebook.ideas.dragonbone.page1.text", "Surely mining these blocks is easy enough when I breach that aura in one swoop beforehand, so it cannot rebuild! Either a magical explosion, or a powerful mundane one, something with a bit more explosive power than just TNT, such as Incandescent Amalgam, should do the trick.");
		provider.add("book.pastel.guidebook.ideas.fading.name", "Experiment #1");
		provider.add("book.pastel.guidebook.ideas.fading.page0.text", "Since Fading is a small and weak, yet lively organism, what about feeding it organic blocks by placing them next to it. When I place the content of the bottle using right-click as a block, I can also bottle them back up.");
		provider.add("book.pastel.guidebook.ideas.fading.page1.text", "They could enjoy the same food as me! How about organic blocks like Pumpkins or Melons - maybe even Leaves! (not to say I enjoy these particularly much). I should place one of those next to a Block of Fading and wait a while.\\\nI am interested what kind of metabolic produce they would yield.");
		provider.add("book.pastel.guidebook.ideas.failing.name", "Experiment #2");
		provider.add("book.pastel.guidebook.ideas.failing.page0.text", "Just like Fading, they prefer a specific food in block form placed next to them. Much stronger this time, though. 'I hate mining this'-strong, to be precise.");
		provider.add("book.pastel.guidebook.ideas.failing.page1.text", "They seem to have insatiable hunger - they eat a lot if given the chance... but looks like their favorite food is Obsidian! Weird taste, but ok.");
		provider.add("book.pastel.guidebook.ideas.malachite.page0.text", "When venturing through the depths, I saw small mineral inclusions in the stone. I did not think too much about them at the time. But now...");
		provider.add("book.pastel.guidebook.ideas.malachite.page1.text", "That bright green ore can be found in the deepest parts of Imbrifer. It's not often found exposed to the air, so the best way to get it is by branch mining.");
		provider.add("book.pastel.guidebook.ideas.mermaids_gems.page0.text", "In a book I raided from a close-by village I saw a depiction of shiny gems, floating on the surface of oceans, being tossed around by the waves.\\\nJust part of a fairy tale, or is there a spark of truth in it?");
		provider.add("book.pastel.guidebook.ideas.mermaids_gems.page1.text", "Not The source of these gem-like seedlings is a coral-like plant that grows in small groups on the seabed, hard to differenciate from sea grass at first. As with most plants, I can Bone Meal it, until it releases its precious treasure. With that knowledge up my sleeve after, I will be able to see the plant for what it is more clearly.");
		provider.add("book.pastel.guidebook.ideas.midnight_chip.page0.text", "This liquid, created during the creation of the Midnight Aberration... it damages every creature it touches.");
		provider.add("book.pastel.guidebook.ideas.midnight_chip.page0.title", "A thought");
		provider.add("book.pastel.guidebook.ideas.midnight_chip.page1.text", "Midnight Solution has different effects depending on what lands in it. Enchanted items lose their magical powers, some items change completely, and creatures killed by it drop a small, mysterious fragment.");
		provider.add("book.pastel.guidebook.ideas.moonstone_cores.page0.text", "The lower plains of Imbrifer appear to have once been home to a highly advanced civilisation.");
		provider.add("book.pastel.guidebook.ideas.moonstone_cores.page1.text", "Some of the cities left behind house a heavily guarded structure. Their protectors appear to be mechanical and very unfriendly, powered by delicate magitech.");
		provider.add("book.pastel.guidebook.ideas.nightdew_sprout.page0.text", "There is something fragrant in the soil, but I can't quite nail down its location... Surely, a keener sense of smell would help here.");
		provider.add("book.pastel.guidebook.ideas.nightdew_sprout.page1.text", "The dormant sprigs of an unusual vine are scattered in the soil beneath my feet. While they are too delicate and elusive for me to dig up, a Sniffer would be naturally suited to the task!");
		provider.add("book.pastel.guidebook.ideas.paltaeria.page0.text", "Even if it seemed that way at the beginning: The end is not just pure end stone.");
		provider.add("book.pastel.guidebook.ideas.paltaeria.page1.text", "I saw an ore both on the central island and in the outer regions of the End, just rarely generating exposed to air, so digging into one of the islands may be my best bet. It has both a common and a rare drop.");
		provider.add("book.pastel.guidebook.ideas.preservation_ruins.name", "3 Structures");
		provider.add("book.pastel.guidebook.ideas.preservation_ruins.page0.text", "A villager told me they found different types of structures made from unbreakable stone hidden near the upper Deepslate layer in the Overworld in every biome.");
		provider.add("book.pastel.guidebook.ideas.preservation_ruins.page1.text", "The entrance seems to be blocked by a powerful force field. However, whoever built it was kind enough to leave me some clues! The hearts on the sides of the force field indicate that I need to have [#](2c2e8e)Azure Dike[#]() active.");
		provider.add("book.pastel.guidebook.ideas.preservation_ruins.page1.title", "Blue Hearts");
		provider.add("book.pastel.guidebook.ideas.preservation_ruins.page2.text", "The Colored Spore Blossoms on the ceiling and the engravings on the walls behind them hint at the solution. The powder engraving hints at $(l:general/color_mixing)the mixing of Gemstone Powder$() I figured out earlier.");
		provider.add("book.pastel.guidebook.ideas.preservation_ruins.page2.title", "Colored Spore Blossoms");
		provider.add("book.pastel.guidebook.ideas.preservation_ruins.page3.text", "Is there a way to crack the Bedrock?\\\nOnce I am inside, it is best to look at the relevant pages in my book for the blocks I find there.");
		provider.add("book.pastel.guidebook.ideas.preservation_ruins.page3.title", "Bedrock Seal");
		provider.add("book.pastel.guidebook.ideas.quitoxic_reeds.page0.text", "Time for an adventure trip on the surface. Somewhere wet and warm such as a Swamp or Mangrove Swamp seems predestined for new discoveries!");
		provider.add("book.pastel.guidebook.ideas.quitoxic_reeds.page1.text", "I noticed strange-looking plants in all sorts of warm, humid places, growing in shallow water on patches of Clay or Mud. In order to grow, they consume Clay/Mud placed around them, turning it into Dirt.");
		provider.add("book.pastel.guidebook.ideas.radiating_ender.page0.text", "I saw an Enderman carrying a block lately. Not a normal one. Something about it seemed... off.");
		provider.add("book.pastel.guidebook.ideas.radiating_ender.page1.text", "Some Endermen appear to carry blocks that could very well be small relics of the End itself. At first I thought it was Cobblestone and it very much looks like one placed down, but if I could get one by killing an Enderman while it is still carrying it, I can get a hold of one. Endermen holding these blocks can also be found in the End, albeit more rarely.");
		provider.add("book.pastel.guidebook.ideas.resonance_shards.page0.text", "Between lakes of [Liquid Crystal](entry://general/liquid_crystal), I often find crystalline structures made up of blocks that take on interesting properties when interacted with.");
		provider.add("book.pastel.guidebook.ideas.resonance_shards.page1.text", "Hummingstones, part of crystal formations in [Crystal Gardens](entry://dimension/crystal_gardens), begin to vibrate when disturbed, causing other nearby Hummingstones in their vicinity vibrate as well. The more there are, the stronger the echo seems to be.");
		provider.add("book.pastel.guidebook.ideas.resonant_lily.page0.text", "In [Crystal Gardens](entry://dimension/crystal_gardens), flowers that grow near [Liquid Crystal](entry://general/liquid_crystal) have strange characteristics. Has their proximity to the liquid changed them?.");
		provider.add("book.pastel.guidebook.ideas.resonant_lily.page1.text", "I don't have that much time to grow a whole new plant like that. But what if I simply throw an existing flower into the liquid to speed up the process?");
		provider.add("book.pastel.guidebook.ideas.ruin.name", "Experiment #3");
		provider.add("book.pastel.guidebook.ideas.ruin.page0.text", "This absolutely aggressive version I called Ruin is capable of consuming the most resilient material there is. Even the one too resistant for me to ever break before.");
		provider.add("book.pastel.guidebook.ideas.ruin.page1.text", "What could be more resilient than the unbreakable Bedrock floor itself? Better have some Decay Away up my sleeve a backup plan in case things get out of hand.");
		provider.add("book.pastel.guidebook.ideas.shimmerstone.page0.text", "As my understanding of the world has expanded, so has my ability to perceive anomalies. I believe I saw a yet unknown yellow ore in the Overworld at and above surface level.");
		provider.add("book.pastel.guidebook.ideas.shimmerstone.page1.text", "It generates in large deposits in all biomes in the middle and upper layers of the Overworld. It is most commonly found exposed in mountains.");
		provider.add("book.pastel.guidebook.ideas.small_clue", "An obervation");
		provider.add("book.pastel.guidebook.ideas.stargazing.page0.text", "I saw a Shooting Star at night not too far from me! It was beautiful. Having something to help me see them in the dark will certainly help spot the next one. They produce a noticeable particle trail.");
		provider.add("book.pastel.guidebook.ideas.stargazing.page0.title", "What to look for");
		provider.add("book.pastel.guidebook.ideas.stargazing.page1.text", "My best chance of seeing a Shooting Star is to look for it with Night Vision and a Spyglass. If I see one crashing down, I'll try to follow its path to find out where it landed. When on the ground they shoot up particles in a beam-like shape.");
		provider.add("book.pastel.guidebook.ideas.storm_stones.page0.text", "Thunderstorms are a powerful display of nature. Enormous energies are at play.");
		provider.add("book.pastel.guidebook.ideas.storm_stones.page1.text", "There was a strange occurence at the place lightning struck. There even is an easy way to focus lightning on a specific location, to make reproducing that phenomenon even more efficient.");
		provider.add("book.pastel.guidebook.ideas.stratine.page0.text", "Some parts of Netherrack struck me more red than others.");
		provider.add("book.pastel.guidebook.ideas.stratine.page1.text", "It almost looked like an ore, most common in the lower layers of the Nether in all biomes below lava level. It has a common and a rare drop.");
		provider.add("book.pastel.guidebook.ideas.topaz.page0.text", "I never knew Geodes could be found at great heights, like on top of hills and sky-high mountains, but here we are.");
		provider.add("book.pastel.guidebook.ideas.where_to_find", "Where to find");
		provider.add("book.pastel.guidebook.ideas.where_to_look", "Where to look");
	}
}
